/**
 * Partner (B2B) paneline giden dış bağlantılar — TEK KAYNAK.
 *
 * Supplier/hotel/operator artık **business** panelinde yaşıyor; eski
 * `supplier.travelshopbooking.com` (dashboardnext) emekliye ayrılıyor. Panelin
 * adresi ya da yolları değişirse yalnız burası güncellenir — sitenin içine
 * hardcoded URL dağıtma.
 */

const BUSINESS_URL = (process.env.NEXT_PUBLIC_BUSINESS_URL ?? "https://business.travelshopbooking.com").replace(/\/+$/, "");

export const partnerLinks = {
  /** Business vitrini (ana sayfa) — tüm B2B çözümlerinin özeti. */
  home: BUSINESS_URL,
  /** Panele giriş (tüm B2B rolleri aynı kapıdan girer). */
  login: `${BUSINESS_URL}/app/login`,
  // business i18n'de `localePrefix: 'as-needed'` → varsayılan dil (en) ön eksiz.
  /** Tur operatörü (acente) başvuru formu. */
  operatorApply: `${BUSINESS_URL}/operators/apply`,
  /** Tur sağlayıcı / DMC başvuru formu. */
  supplierApply: `${BUSINESS_URL}/suppliers/apply`,
  /** Otel başvuru formu. */
  hotelApply: `${BUSINESS_URL}/hotels/apply`,
  /** Affiliate programı tanıtım sayfası (başvuru oradan). */
  affiliates: `${BUSINESS_URL}/affiliates`,
  /** Blogger başvuru formu (eski tsbnext /blogger/register). */
  bloggerApply: `${BUSINESS_URL}/bloggers/apply`,
} as const;
